const nomesUnissexo = new Set(['alex', 'ariel', 'dominique']);

function estimarGenero(primeiroNome) {
    if (!primeiroNome || typeof primeiroNome !== 'string') {
        return "Indefinido";
    }
    const nome = normalizar(primeiroNome);

    if (nomesUnissexo.has(nome)) return "Indefinido";
    if (nomesFemininos.has(nome)) return "Feminino";
    if (nomesMasculinos.has(nome)) return "Masculino";

    // Heurística por terminação (fallback)
    if (nome.endsWith('a') || nome.endsWith('z')) return "Feminino";
    if (['o', 'e', 'r', 'l', 'u'].some(t => nome.endsWith(t))) return "Masculino";

    return "Indefinido";
}

// --- Processa todos os itens do lote de uma vez ---
return $input.all().map(item => {
    const genero = estimarGenero(item.json.primeiroNome);
    return {
        json: {
            ...item.json,
            genero
        }
    };
});

